create or replace function public.repair_published_test_item_texts(p_package_version_id uuid,p_repairs jsonb,p_reason text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare v_repair_id uuid:=gen_random_uuid(); v_org_id uuid; v_actor uuid:=public.current_staff_user_id(); v_status text; v_original_published_at timestamptz; v_patch jsonb; v_item public.test_items%rowtype; v_text_vi text; v_text_en text; v_target_language text; v_audit jsonb:='[]'::jsonb; v_count int:=0; begin if coalesce(auth.role(),'')<>'service_role' and session_user<>'postgres' then raise exception 'Text repair requires service_role' using errcode='42501'; end if; if jsonb_typeof(p_repairs)<>'array' or jsonb_array_length(p_repairs)=0 then raise exception 'p_repairs must be a non-empty JSON array'; end if; if length(trim(coalesce(p_reason,'')))<8 then raise exception 'A repair reason of at least 8 characters is required'; end if; select p.organization_id,v.status,v.published_at into v_org_id,v_status,v_original_published_at from public.test_package_versions v join public.test_packages p on p.id=v.package_id where v.id=p_package_version_id for update of v; if v_org_id is null then raise exception 'Package Version not found'; end if; if v_status<>'published' then raise exception 'Package Version must be published'; end if; insert into public.package_version_text_repairs(id,organization_id,package_version_id,reason,status,requested_by_user_id) values(v_repair_id,v_org_id,p_package_version_id,trim(p_reason),'running',v_actor); perform set_config('app.package_text_repair_id',v_repair_id::text,true); update public.test_package_versions set status='draft',published_at=null where id=p_package_version_id; for v_patch in select value from jsonb_array_elements(p_repairs) loop if not(v_patch?'sectionOrder' and v_patch?'itemOrder') then raise exception 'Each patch requires sectionOrder and itemOrder'; end if; select i.* into v_item from public.test_items i join public.test_sections s on s.id=i.section_id where i.package_version_id=p_package_version_id and s.section_order=(v_patch->>'sectionOrder')::int and i.item_order=(v_patch->>'itemOrder')::int for update; if v_item.id is null then raise exception 'Item not found for section % item %',v_patch->>'sectionOrder',v_patch->>'itemOrder'; end if; v_text_vi:=coalesce(v_patch->>'textVi',v_item.prompt_vi); v_text_en:=coalesce(v_patch->>'textEn',v_item.prompt_en); v_target_language:=coalesce(v_patch->>'targetLanguage',v_item.source_metadata->>'targetLanguage'); if nullif(trim(v_text_vi),'') is null or nullif(trim(v_text_en),'') is null then raise exception 'Both VI and EN text are required'; end if; if v_target_language not in('vi','en') then raise exception 'targetLanguage must be vi or en'; end if; v_audit:=v_audit||jsonb_build_array(jsonb_build_object('itemId',v_item.id,'sectionOrder',(v_patch->>'sectionOrder')::int,'itemOrder',(v_patch->>'itemOrder')::int,'before',jsonb_build_object('termVi',v_item.term_vi,'promptVi',v_item.prompt_vi,'spokenScriptVi',v_item.spoken_script_vi,'termEn',v_item.term_en,'promptEn',v_item.prompt_en,'spokenScriptEn',v_item.spoken_script_en,'targetLanguage',v_item.source_metadata->>'targetLanguage'),'after',jsonb_build_object('termVi',v_text_vi,'promptVi',v_text_vi,'spokenScriptVi',v_text_vi,'termEn',v_text_en,'promptEn',v_text_en,'spokenScriptEn',v_text_en,'targetLanguage',v_target_language))); update public.test_items set term_vi=v_text_vi,prompt_vi=v_text_vi,spoken_script_vi=v_text_vi,term_en=v_text_en,prompt_en=v_text_en,spoken_script_en=v_text_en,source_metadata=jsonb_set(jsonb_set(source_metadata,'{targetLanguage}',to_jsonb(v_target_language),true),'{audioPlan,language}',to_jsonb(v_target_language),true)||jsonb_build_object('lastTextRepair',jsonb_build_object('repairId',v_repair_id,'reason',trim(p_reason),'repairedAt',now())) where id=v_item.id; v_count:=v_count+1; end loop; update public.test_package_versions set source_metadata=source_metadata||jsonb_build_object('lastTextRepairId',v_repair_id,'lastTextRepairAt',now(),'lastTextRepairReason',trim(p_reason)),status='published',published_at=v_original_published_at where id=p_package_version_id; update public.package_version_text_repairs set status='completed',repairs=v_audit,completed_at=now() where id=v_repair_id; perform set_config('app.package_text_repair_id','',true); return jsonb_build_object('repairId',v_repair_id,'packageVersionId',p_package_version_id,'status','published','publishedAt',v_original_published_at,'repairedItems',v_count); end; $$; revoke execute on function public.repair_published_test_item_texts(uuid,jsonb,text) from public,anon,authenticated; grant execute on function public.repair_published_test_item_texts(uuid,jsonb,text) to service_role;;
